    {\LARGE\bfseries Toward a Real Lightsaber: Polariton Condensate Blade Architecture Using Perovskite Crystal Substrates and Carbon Nanotube Waveguides\par}

    \vspace{1.5cm}

    {\large Rickey Jay Bennett II\par}
    {\normalsize Independent Researcher\par}
    {\normalsize \href{mailto:independant_researcher@rickeyjaybennettii.org}{independant\_researcher@rickeyjaybennettii.org}\par}

