  return new TableCell({
    borders,
    width: { size: widthDXA, type: WidthType.DXA },
    shading: shaded ? { fill: "E8E8E8", type: ShadingType.CLEAR } : { fill: "FFFFFF", type: ShadingType.CLEAR },
    margins: { top: 80, bottom: 80, left: 120, right: 120 },
    children: [new Paragraph({
      children: [new TextRun({ text, bold, font: "Courier New", size: 20 })]
    })]
  });
}

function headerCell(text, widthDXA) {
  return new TableCell({
    borders: headerBorders,
    width: { size: widthDXA, type: WidthType.DXA },
    shading: { fill: "222222", type: ShadingType.CLEAR },
    margins: { top: 80, bottom: 80, left: 120, right: 120 },
    children: [new Paragraph({
      children: [new TextRun({ text, bold: true, color: "FFFFFF", font: "Courier New", size: 20 })]
    })]
